#include <iostream>
using namespace std;

int main()
{
    int x, t, a, b, da, db;
    int ta, tb, dbtb;

    cin >> x >> t >> a >> b >> da >> db;

    int c = a + b - x;
    bool p = false;

    if (x == 0)
        p = true;
    else if (a == x || b == x)
        p = true;
    else if ((x - a) % da == 0)
    {
        ta = (x - a) / da;
        if (ta < t && ta >= 0)
            p = true;
    }
    else if ((x - b) % db == 0)
    {
        tb = (x - b) / db;
        if (tb < t && tb >= 0)
            p = true;
    }
    else if (c == 0)
        p = true;
    else
    {
        for (ta = 0; ta < t; ta++)
        {
            dbtb = c - da * ta;

            if (dbtb == 0)
            {
                p = true;
                break;
            }

            if (dbtb % db == 0)
            {
                tb = dbtb / db;
                if (tb >= 0 && tb < t)
                {
                    p = true;
                    break;
                }
            }
        }
    }

    cout << (p ? "YES" : "NO");
    return 0;
}

